package com.taskmate.ui.components;
import com.taskmate.dao.TaskDao;import com.taskmate.dao.AdminDao;import com.taskmate.models.*;import com.taskmate.services.TaskService;import com.taskmate.database.Database;import com.taskmate.ui.auth.LoginFrame;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;import java.time.LocalDate;import java.util.*;
public class DashboardFrame extends JFrame {
 private final User user;private final TaskService service=new TaskService();private final JPanel body=new JPanel(new BorderLayout(12,12));
 public DashboardFrame(User u){super("TaskMate | "+u.role()+" Dashboard");user=u;setDefaultCloseOperation(EXIT_ON_CLOSE);setMinimumSize(new Dimension(1000,650));setSize(1180,760);setLocationRelativeTo(null);setLayout(new BorderLayout());JPanel side=new JPanel();side.setBackground(new Color(19,67,51));side.setLayout(new BoxLayout(side,BoxLayout.Y_AXIS));side.setBorder(BorderFactory.createEmptyBorder(18,12,18,12));JLabel brand=new JLabel("  TaskMate");brand.setForeground(Color.WHITE);brand.setFont(brand.getFont().deriveFont(Font.BOLD,22f));side.add(brand);side.add(Box.createVerticalStrut(24));JLabel who=new JLabel("  "+u.name()+" · "+u.role());who.setForeground(new Color(215,235,224));side.add(who);side.add(Box.createVerticalStrut(18));java.util.ArrayList<String> pages=new java.util.ArrayList<>(java.util.List.of("Overview","Tasks","Courses","Attendance"));if(u.role().equals("HOD"))pages.add("Accounts");for(String page:pages){JButton b=new JButton(page);b.setAlignmentX(LEFT_ALIGNMENT);b.setMaximumSize(new Dimension(220,38));b.addActionListener(e->show(page));side.add(b);side.add(Box.createVerticalStrut(7));}side.add(Box.createVerticalGlue());JButton logout=new JButton("Log out");logout.addActionListener(e->{dispose();LoginFrame.launch();});side.add(logout);add(side,BorderLayout.WEST);body.setBorder(BorderFactory.createEmptyBorder(22,22,22,22));add(body);show("Overview");}
 private void show(String page){body.removeAll();JLabel heading=new JLabel(page);heading.setFont(heading.getFont().deriveFont(Font.BOLD,25f));JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);top.add(heading,BorderLayout.WEST);body.add(top,BorderLayout.NORTH);try{switch(page){case "Tasks"->tasks();case "Courses"->courses();case "Attendance"->attendance();case "Accounts"->accounts();default->overview();}}catch(Exception e){body.add(new JLabel("Could not load data: "+e.getMessage()),BorderLayout.CENTER);}body.revalidate();body.repaint();}
 private void overview()throws Exception{JPanel cards=new JPanel(new GridLayout(1,4,12,12));String[] labels=user.role().equals("HOD")?new String[]{"Faculty","Students","Courses","Assignments"}:user.role().equals("FACULTY")?new String[]{"My courses","My assignments","Pending submissions","Evaluated"}:new String[]{"My courses","Assignments","Pending","Evaluated"};String[] queries=user.role().equals("HOD")?new String[]{"SELECT COUNT(*) FROM users WHERE role='FACULTY' AND is_active=1","SELECT COUNT(*) FROM users WHERE role='STUDENT' AND is_active=1","SELECT COUNT(*) FROM courses","SELECT COUNT(*) FROM tasks"}:user.role().equals("FACULTY")?new String[]{"SELECT COUNT(*) FROM courses WHERE faculty_id=?","SELECT COUNT(*) FROM tasks WHERE faculty_id=?","SELECT COUNT(*) FROM submissions s JOIN tasks t ON t.id=s.task_id WHERE t.faculty_id=? AND s.status='SUBMITTED'","SELECT COUNT(*) FROM submissions s JOIN tasks t ON t.id=s.task_id WHERE t.faculty_id=? AND s.status='EVALUATED'"}:new String[]{"SELECT COUNT(*) FROM enrollments WHERE student_id=?","SELECT COUNT(*) FROM submissions WHERE student_id=?","SELECT COUNT(*) FROM submissions WHERE student_id=? AND status='PENDING'","SELECT COUNT(*) FROM submissions WHERE student_id=? AND status='EVALUATED'"};for(int i=0;i<labels.length;i++){long n=count(queries[i]);JPanel card=new JPanel(new BorderLayout());card.setBackground(new Color(235,245,239));card.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));JLabel value=new JLabel(""+n);value.setFont(value.getFont().deriveFont(Font.BOLD,30f));card.add(new JLabel(labels[i]),BorderLayout.NORTH);card.add(value,BorderLayout.CENTER);cards.add(card);}body.add(cards,BorderLayout.CENTER);JButton refresh=new JButton("Refresh data");refresh.addActionListener(e->show("Overview"));JPanel footer=new JPanel(new FlowLayout(FlowLayout.LEFT));footer.add(refresh);body.add(footer,BorderLayout.SOUTH);}
 private long count(String q)throws SQLException{try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){if(q.contains("?"))p.setLong(1,user.id());try(ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}}
 private void tasks()throws Exception{var all=service.tasks(user);String[] cols={"ID","Task","Course","Type","Due","Priority","Max marks","Status","Marks","Faculty"};DefaultTableModel m=new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};for(Task t:all)m.addRow(new Object[]{t.id(),t.title(),t.course(),t.type(),t.dueDate(),t.priority(),t.maxMarks(),service.taskStatus(t),t.marks()==null?"—":t.marks(),t.faculty()});JTable table=new JTable(m);table.setRowHeight(27);JPanel wrap=new JPanel(new BorderLayout(8,8));JTextField search=new JTextField();search.putClientProperty("JTextField.placeholderText","Search task, course, type…");search.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){public void insertUpdate(javax.swing.event.DocumentEvent e){filter();}public void removeUpdate(javax.swing.event.DocumentEvent e){filter();}public void changedUpdate(javax.swing.event.DocumentEvent e){filter();}void filter(){String q=search.getText().toLowerCase();m.setRowCount(0);for(Task t:all)if((t.title()+t.course()+t.type()+t.status()).toLowerCase().contains(q))m.addRow(new Object[]{t.id(),t.title(),t.course(),t.type(),t.dueDate(),t.priority(),t.maxMarks(),service.taskStatus(t),t.marks()==null?"—":t.marks(),t.faculty()});}});wrap.add(search,BorderLayout.NORTH);wrap.add(new JScrollPane(table));JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));if(user.role().equals("FACULTY")){JButton create=new JButton("Create task");create.addActionListener(e->createTask());actions.add(create);JButton evaluate=new JButton("Evaluate selected task");evaluate.addActionListener(e->evaluateSelected(table,m));actions.add(evaluate);}if(user.role().equals("STUDENT")){JButton submit=new JButton("Submit selected task");submit.addActionListener(e->{int r=table.getSelectedRow();if(r<0)return;try{service.submit(user,((Number)m.getValueAt(r,0)).longValue());JOptionPane.showMessageDialog(this,"Submitted.");show("Tasks");}catch(Exception ex){error(ex);}});actions.add(submit);}wrap.add(actions,BorderLayout.SOUTH);body.add(wrap,BorderLayout.CENTER);}
 private void evaluateSelected(JTable table,DefaultTableModel taskModel){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a task first.");return;}try{long task=((Number)taskModel.getValueAt(row,0)).longValue();var submissions=service.submissionsForTask(user,task);if(submissions.isEmpty()){JOptionPane.showMessageDialog(this,"No submitted or evaluated student work for this task.");return;}String[] opts=submissions.stream().map(s->s[0]+" · "+s[1]+" ("+s[2]+")").toArray(String[]::new);String selected=(String)JOptionPane.showInputDialog(this,"Submission","Evaluate",JOptionPane.PLAIN_MESSAGE,null,opts,opts[0]);if(selected==null)return;long submission=Long.parseLong(selected.split(" · ")[0]);String entered=JOptionPane.showInputDialog(this,"Marks (maximum "+taskModel.getValueAt(row,6)+")");if(entered==null)return;String feedback=JOptionPane.showInputDialog(this,"Feedback");service.evaluate(user,submission,Double.parseDouble(entered),feedback==null?"":feedback);JOptionPane.showMessageDialog(this,"Evaluation saved.");show("Tasks");}catch(Exception ex){error(ex);}}
 private void createTask(){try{var courses=service.courses(user);if(courses.isEmpty()){JOptionPane.showMessageDialog(this,"No courses are assigned to your account.");return;}String[] options=courses.stream().map(c->c[0]+" · "+c[1]+" "+c[2]).toArray(String[]::new);String chosen=(String)JOptionPane.showInputDialog(this,"Course","Create academic task",JOptionPane.PLAIN_MESSAGE,null,options,options[0]);if(chosen==null)return;long course=Long.parseLong(chosen.split(" · ")[0]);String title=JOptionPane.showInputDialog(this,"Title");if(title==null)return;String desc=JOptionPane.showInputDialog(this,"Description (optional)");String type=(String)JOptionPane.showInputDialog(this,"Task type","Type",JOptionPane.PLAIN_MESSAGE,null,new String[]{"ASSIGNMENT","QUIZ","ASSESSMENT"},"ASSIGNMENT");String due=JOptionPane.showInputDialog(this,"Deadline (YYYY-MM-DD)",LocalDate.now().plusDays(7));String priority=(String)JOptionPane.showInputDialog(this,"Priority","Priority",JOptionPane.PLAIN_MESSAGE,null,new String[]{"HIGH","MEDIUM","LOW"},"MEDIUM");String marks=JOptionPane.showInputDialog(this,"Maximum marks","100");service.create(user,course,title,desc==null?"":desc,type,LocalDate.parse(due),priority,Double.parseDouble(marks));JOptionPane.showMessageDialog(this,"Task created; pending submission rows generated for enrolled students.");show("Tasks");}catch(Exception ex){error(ex);}}
 private void courses()throws Exception{var cs=service.courses(user);String[] cols={"ID","Code","Course","Year","Section","Faculty","Students"};DefaultTableModel m=new DefaultTableModel(cols,0);cs.forEach(m::addRow);body.add(new JScrollPane(new JTable(m)),BorderLayout.CENTER);}
 private void accounts()throws Exception{AdminDao dao=new AdminDao();DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Name","Email","Role","Department","Year","Section","Active"},0){public boolean isCellEditable(int r,int c){return false;}};for(Object[] row:dao.users(user))m.addRow(row);JTable table=new JTable(m);table.setRowHeight(26);JPanel p=new JPanel(new BorderLayout(8,8));p.add(new JScrollPane(table));JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton add=new JButton("Create faculty/student");add.addActionListener(e->{try{String name=JOptionPane.showInputDialog(this,"Full name");if(name==null)return;String email=JOptionPane.showInputDialog(this,"Email");if(email==null)return;String role=(String)JOptionPane.showInputDialog(this,"Role","New account",JOptionPane.PLAIN_MESSAGE,null,new String[]{"FACULTY","STUDENT"},"STUDENT");if(role==null)return;String dept=JOptionPane.showInputDialog(this,"Department",user.department());if(dept==null)return;String year=role.equals("STUDENT")?JOptionPane.showInputDialog(this,"Academic year (e.g. 2)",""):"";String section=role.equals("STUDENT")?JOptionPane.showInputDialog(this,"Section",""):"";JPasswordField field=new JPasswordField();if(JOptionPane.showConfirmDialog(this,field,"Set temporary password (10+ characters)",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;char[] pass=field.getPassword();try{dao.createUser(user,name,email,pass,role,dept,year==null?"":year,section==null?"":section);}finally{Arrays.fill(pass,'\0');}JOptionPane.showMessageDialog(this,"Account created. Give the password securely to the user.");show("Accounts");}catch(Exception ex){error(ex);}});JButton toggle=new JButton("Activate/deactivate selected");toggle.addActionListener(e->{int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select an account first.");return;}try{boolean active=(Boolean)m.getValueAt(row,7);dao.setActive(user,((Number)m.getValueAt(row,0)).longValue(),!active);show("Accounts");}catch(Exception ex){error(ex);}});buttons.add(add);buttons.add(toggle);p.add(buttons,BorderLayout.SOUTH);body.add(p,BorderLayout.CENTER);}
 private void attendance()throws Exception{String q=user.role().equals("HOD")?"SELECT c.course_code,u.name,a.class_date,a.attendance_status,m.name FROM attendance a JOIN courses c ON c.id=a.course_id JOIN users u ON u.id=a.student_id JOIN users m ON m.id=a.marked_by ORDER BY a.class_date DESC":"SELECT c.course_code,u.name,a.class_date,a.attendance_status,m.name FROM attendance a JOIN courses c ON c.id=a.course_id JOIN users u ON u.id=a.student_id JOIN users m ON m.id=a.marked_by WHERE "+(user.role().equals("FACULTY")?"c.faculty_id=?":"a.student_id=?")+" ORDER BY a.class_date DESC";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){if(!user.role().equals("HOD"))p.setLong(1,user.id());try(ResultSet r=p.executeQuery()){DefaultTableModel m=new DefaultTableModel(new String[]{"Course","Student","Date","Status","Marked by"},0);while(r.next())m.addRow(new Object[]{r.getString(1),r.getString(2),r.getDate(3),r.getString(4),r.getString(5)});body.add(new JScrollPane(new JTable(m)),BorderLayout.CENTER);}}}
 private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Action failed",JOptionPane.ERROR_MESSAGE);}
}
